begin;
create function pg_temp.t_id(n integer) returns uuid language sql immutable as $$select ('b2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.t_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.t_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected %',state;end$$;
create function pg_temp.t_probe(n integer,name text,reg text default null) returns jsonb language sql as $$select jsonb_build_object('rowId',pg_temp.t_id(n),'name',name,'nickname',null,'birthDate',null,'birthYear',null,'federationRegistration',reg)$$;
create function pg_temp.t_document() returns jsonb language sql as $$select jsonb_build_object('id',pg_temp.t_id(2),'disputeId',pg_temp.t_id(92),'text',E'Equipe: Time\n7 - Nova','teamName','Time','target',jsonb_build_object('kind','registration','registrationId',pg_temp.t_id(95),'version',1),
 'ignoredLines',jsonb_build_array(jsonb_build_object('line',1,'source','Equipe: Time','kind','team')),'issues','[]'::jsonb,
 'rows',jsonb_build_array(jsonb_build_object('id',pg_temp.t_id(10),'line',2,'source','7 - Nova','selected',true,'rosterId',pg_temp.t_id(11),'rosterVersion',0,'decision',null,'issues','[]'::jsonb,'provided',jsonb_build_array('name','jersey'),
 'data',jsonb_build_object('name','Nova','jersey','7','nickname',null,'birthDate',null,'birthYear',null,'positions','[]'::jsonb,'heightCm',null,'weightKg',null,'dominantHand','right','federationRegistration',null))))$$;
create function pg_temp.t_command() returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.t_id(1),'expectedVersion',0,'review',pg_temp.t_document())$$;
grant execute on function pg_temp.t_id(integer),pg_temp.t_assert(boolean,text),pg_temp.t_error(text,text),pg_temp.t_probe(integer,text,text),pg_temp.t_document(),pg_temp.t_command() to anon,authenticated;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.t_id(98)),(pg_temp.t_id(99));
insert into public.admin_access(user_id) values(pg_temp.t_id(98));
insert into public.championships(id,name) values(pg_temp.t_id(90),'Text review');
insert into public.seasons(id,championship_id,year) values(pg_temp.t_id(91),pg_temp.t_id(90),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.t_id(92),pg_temp.t_id(91),'feminino','Adulto');
insert into public.teams(id,name) values(pg_temp.t_id(94),'Team');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.t_id(95),pg_temp.t_id(92),pg_temp.t_id(94),'Time'),(pg_temp.t_id(96),pg_temp.t_id(92),pg_temp.t_id(94),'Outra');
insert into public.persons(id,name,nickname) values(pg_temp.t_id(50),'João Silva','JS'),(pg_temp.t_id(51),'Joao Silva',null),(pg_temp.t_id(52),'Luka Silva',null);
insert into private.athletes(person_id,sex,federation_registration,birth_year) values(pg_temp.t_id(50),'female','001234',1999),(pg_temp.t_id(51),'female',null,2001),(pg_temp.t_id(52),'female',null,null);
insert into public.roster_entries(id,registration_id,dispute_id,person_id,jersey) values(pg_temp.t_id(60),pg_temp.t_id(96),pg_temp.t_id(92),pg_temp.t_id(50),'0');
set local role anon;
select pg_temp.t_error('select public.get_text_review(pg_temp.t_id(2))','42501');
set local role authenticated;
set local request.jwt.claim.sub='b2000000-0000-4000-8000-000000000099';
select pg_temp.t_assert(public.get_import_person(pg_temp.t_id(50),pg_temp.t_id(92),pg_temp.t_id(95)) is null,'other authenticated cannot see private import candidate');
select pg_temp.t_error('select public.save_text_review(pg_temp.t_command())','PT403');
select pg_temp.t_error($q$select public.match_import_players(pg_temp.t_id(92),pg_temp.t_id(95),jsonb_build_array(pg_temp.t_probe(10,'João Silva')))$q$,'PT403');
set local request.jwt.claim.sub='b2000000-0000-4000-8000-000000000098';
select pg_temp.t_assert((public.save_text_review(pg_temp.t_command())->>'version')::int=1,'unresolved review saved');
select pg_temp.t_assert((public.save_text_review(pg_temp.t_command())->>'version')::int=1,'save replay');
select pg_temp.t_error($q$select public.save_text_review(jsonb_set(pg_temp.t_command(),'{review,rows,0,data,name}','"changed"'))$q$,'PT409');
select pg_temp.t_error($q$select public.save_text_review(jsonb_set(pg_temp.t_command(),'{commandId}',to_jsonb(pg_temp.t_id(3))))$q$,'PT409');
select pg_temp.t_assert(public.get_text_review(pg_temp.t_id(2))->'rows'->0->>'source'='7 - Nova','raw line retained');
select pg_temp.t_assert(jsonb_array_length(public.list_text_reviews(pg_temp.t_id(92))->'items')=1,'review can be resumed by context');
select pg_temp.t_error('delete from private.text_reviews','42501');
select pg_temp.t_error('select * from private.text_review_commands','42501');
select pg_temp.t_error($q$select public.save_text_review(jsonb_set(jsonb_set(pg_temp.t_command(),'{commandId}',to_jsonb(pg_temp.t_id(3))),'{review,rows,0,source}','"forged"'))$q$,'PT400');
select pg_temp.t_error($q$select public.save_text_review(jsonb_set(jsonb_set(pg_temp.t_command(),'{commandId}',to_jsonb(pg_temp.t_id(3))),'{review,results}','[]'))$q$,'PT400');
select pg_temp.t_error($q$select public.save_text_review(jsonb_set(jsonb_set(pg_temp.t_command(),'{commandId}',to_jsonb(pg_temp.t_id(3))),'{review,ignoredLines,0,kind}','null'))$q$,'PT400');
select pg_temp.t_error($q$select public.save_text_review(jsonb_set(jsonb_set(pg_temp.t_command(),'{commandId}',to_jsonb(pg_temp.t_id(3))),'{expectedVersion}','"1"'))$q$,'PT400');
select pg_temp.t_assert((public.save_text_review(jsonb_set(jsonb_set(jsonb_set(pg_temp.t_command(),'{commandId}',to_jsonb(pg_temp.t_id(3))),'{expectedVersion}','1'),'{review,rows,0,data,nickname}','"Revisado"'))->>'version')::int=2,'review decisions can be saved with expected version');
select pg_temp.t_assert(public.get_text_review(pg_temp.t_id(2))->'rows'->0->'data'->>'nickname'='Revisado','saved correction survives reload');
select pg_temp.t_assert(public.match_import_players(pg_temp.t_id(92),pg_temp.t_id(95),jsonb_build_array(pg_temp.t_probe(10,'Other','001234')))->'items'->0->>'status'='registration','federation match precedes name');
select pg_temp.t_assert(public.match_import_players(pg_temp.t_id(92),pg_temp.t_id(95),jsonb_build_array(pg_temp.t_probe(10,'JOAO SILVA')))->'items'->0->>'status'='ambiguous','normalized homonyms remain ambiguous');
select pg_temp.t_assert(public.match_import_players(pg_temp.t_id(92),pg_temp.t_id(95),jsonb_build_array(jsonb_set(pg_temp.t_probe(10,'Joao Silva'),'{birthYear}','2001')))->'items'->0->'candidates'->0->>'id'=pg_temp.t_id(51)::text,'partial private birth year helps order ambiguous suggestions');
select pg_temp.t_assert(public.match_import_players(pg_temp.t_id(92),pg_temp.t_id(95),jsonb_build_array(pg_temp.t_probe(10,'Luke Silva')))->'items'->0->>'status'='suggestion','similar name is suggestion only');
select pg_temp.t_assert(public.match_import_players(pg_temp.t_id(92),pg_temp.t_id(95),jsonb_build_array(pg_temp.t_probe(10,'Zebra Lunar')))->'items'->0->>'status'='new','unmatched identity is a new proposal');
select pg_temp.t_assert(public.match_import_players_new_target(pg_temp.t_id(92),jsonb_build_array(pg_temp.t_probe(10,'Other','001234')))->'items'->0->'candidates'->0->>'activeRegistrationId'=pg_temp.t_id(96)::text,'unsaved target matching still reports active memberships in this dispute');
select pg_temp.t_error($q$select public.match_import_players(pg_temp.t_id(92),pg_temp.t_id(95),jsonb_build_array(jsonb_set(pg_temp.t_probe(10,'Nova'),'{birthDate}','"2001-02-29"')))$q$,'PT400');
select pg_temp.t_assert(public.get_import_person(pg_temp.t_id(50),pg_temp.t_id(92),pg_temp.t_id(95))->'data'->>'birthYear'='1999' and public.get_import_person(pg_temp.t_id(50),pg_temp.t_id(92),pg_temp.t_id(95))->>'activeRegistrationId'=pg_temp.t_id(96)::text,'private partial year and contextual conflict available only to admin');
reset role;
update public.admin_access set enabled=false;
set local role authenticated;
select pg_temp.t_assert(public.get_text_review(pg_temp.t_id(2)) is null and jsonb_array_length(public.list_text_reviews(pg_temp.t_id(92))->'items')=0,'revoked review reads');
select pg_temp.t_error('select public.save_text_review(pg_temp.t_command())','PT403');
reset role;
rollback;
